        difficultyReason = "Multiple setup mechanics, a six-dungeon potion route and some easier-to-coordinate group interactions.",
        commentIds = { 1962753, 1724855, 1701011, 1798070, 1720508 },
        tips = "Track 6927 and the specific sub-achievement before each pull. Remove damage procs, dismiss damaging pets and stop auto-attacking when a boss must survive. Failed Heroic boss kills can cost the rest of today's attempt.",
        waypoints = {
            { mapID = 22, x = 0.691, y = 0.737, step = 1, label = "Current Scholomance - potion and school achievements" },
