        waypoints = {
            { mapID = 379, x = 0.535, y = 0.653, step = 1, label = "Sha of Anger - outdoor boss spawn area" },
            { mapID = 554, x = 0.428, y = 0.556, step = 2, label = "Mistweaver Ai - bonus-roll currency exchanges" },
        },
        reviewedAt = "2026-11-13",
        itemId = 87771,
        name = "Heavenly Onyx Cloud Serpent",
        wowheadUrl = "https://www.wowhead.com/item=87771",
        mountCategory = "Rare Drops",
        stepCount = 5,
        acquisition = "Difficulty: Hard - The legacy fight is easy, but random loot and weekly character eligibility can require repeated resets.\n\n1. Travel to Kun-Lai Summit and wait at Sha of Anger's marked spawn area. Check that you are in the same War Mode/phase as anyone sharing the spawn.\n\n2. Before pulling, check whether this character has already looted Sha of Anger this week. For an additional eligible roll, bring a Elder Charm of Good Fortune. Elder Charms can be bought from Mistweaver Ai on the Timeless Isle; Mogu Runes come from Mistweaver Ai's exchange for Timeless Coins.\n\n3. When the boss is attackable, land a damaging hit while it is alive. Let other waiting players tag it; merely standing nearby or arriving after the kill is not a dependable loot claim.\n\n4. Kill Sha of Anger, check the personal-loot result and use the bonus-roll prompt if you brought the correct token. This outdoor boss can award its mount on a bonus roll; this rule does not apply to instanced raid mounts.\n\n5. If Heavenly Onyx Cloud Serpent is awarded, use its mount item. Otherwise return after the weekly reset or use a different eligible character. Waiting for a respawn on the same already-looted character does not refresh the normal weekly chance.",
    },
    [127161] = {
        category = "Achievements",
        source = "Glory of the Pandaria Raider (6932)",
        sourceAchievementId = 6932,
        description = "A personal raid meta spanning Mogu'shan Vaults, Heart of Fear and Terrace of Endless Spring. It is separate from the guild meta.",
        difficulty = "hard",
        difficultyReason = "Several mechanics need deliberate setup and helpers; Protector kill-order credit requires repeated eligible clears.",
        commentIds = { 1779420, 2524716, 1736169, 2271247, 2315327, 2627011, 1762413, 1763511 },
        tips = "Use Heroic to combine required Heroic boss credits with mechanics when practical. Getting Hot In Here and Show Me Your Moves are no longer in this meta; Heroic Sha of Fear is not required. Check the current criterion list.",
        waypoints = {
            { mapID = 379, x = 0.596, y = 0.391, step = 2, label = "Mogu'shan Vaults - Stone Guard / canine pets" },
            { mapID = 379, x = 0.596, y = 0.391, step = 3, label = "Vaults - Feng reversal setup" },
            { mapID = 379, x = 0.596, y = 0.391, step = 4, label = "Vaults - Gara'jal artifact" },
            { mapID = 379, x = 0.596, y = 0.391, step = 5, label = "Vaults - six Elegon focuses" },
            { mapID = 422, x = 0.39, y = 0.35, step = 6, label = "Heart of Fear - Zor'lok parasites" },
            { mapID = 422, x = 0.39, y = 0.35, step = 7, label = "Heart of Fear - four Ta'yak braziers" },
            { mapID = 422, x = 0.39, y = 0.35, step = 8, label = "Heart of Fear - Garalon / Mel'jarak" },
            { mapID = 422, x = 0.39, y = 0.35, step = 9, label = "Heart of Fear - eight amber pools" },
            { mapID = 422, x = 0.39, y = 0.35, step = 10, label = "Heart of Fear - Empress Reavers" },
            { mapID = 433, x = 0.485, y = 0.616, step = 11, label = "Terrace of Endless Spring - three Protector orders" },
            { mapID = 433, x = 0.485, y = 0.616, step = 12, label = "Terrace - Enchanted Plant" },
            { mapID = 433, x = 0.485, y = 0.616, step = 13, label = "Terrace - Lei Shi parasites" },
            { mapID = 433, x = 0.485, y = 0.616, step = 14, label = "Terrace - Sha of Fear" },
        },
        reviewedAt = "2026-11-13",
        itemId = 87773,
        name = "Heavenly Crimson Cloud Serpent",
        wowheadUrl = "https://www.wowhead.com/item=87773",
        mountCategory = "Achievements",
        stepCount = 15,
        acquisition = "Difficulty: Hard - Several mechanics need deliberate setup and helpers; Protector kill-order credit requires repeated eligible clears.\n\n1. Track 6932. Bring a tank-specialized character and helpers for Feng's copied abilities and Gara'jal's spirit-world artifact; do not assume legacy damage makes every criterion soloable. Remove damage procs before setup fights.\n\n2. Enter Heroic Mogu'shan Vaults in Kun-Lai. Summon a canine companion pet on EVERY raid member before killing Stone Guard for Must Love Dogs. Keep it summoned through the kill.\n\n3. At Feng, let the tank take Shroud of Reversal from its crystal. Copy Epicenter, Lightning Fists, Wildfire Spark, Arcane Velocity and Arcane Resonance from the appropriate targeted ally/ability, then cast each copied spell before killing Feng. A tank plus another player is the dependable setup; use additional visits if some copies are missing.\n\n4. At Gara'jal, keep the boss alive, use Spirit Totems to enter the spirit world and channel the Ancient Mogu Artifact. Coordinate multiple non-tank channelers and another group if the first portal window is insufficient; the artifact credit must register before you finish the encounter.\n\n5. At Elegon, advance to the six Empyreal Focus pillars, prepare their health and deactivate all six within ten seconds for Straight Six. Finish all six Vaults bosses on Heroic for the listed Heroic credits.\n\n6. Enter Heroic Heart of Fear in the Dread Wastes. On Zor'lok, each player clicks a glowing Zealous Parasite near the pillars after the pull. Confirm everyone has the debuff before the kill; collecting a parasite is not tied to the last phase.\n\n7. On Ta'yak, stop damage around 20%. Take Flame Bearer from a burning central brazier and light both unlit end braziers; refresh the thirty-second buff and light the opposite end's pair. Kill him only after all four are lit. Avoid accidental damage through the 20% and 10% transitions.\n\n8. Kill Garalon without destroying any leg for Like an Arrow to the Face. Kill Mel'jarak while crowd-controlling no more than two swarm adds simultaneously for Less Than Three; high-level burst with no crowd control satisfies that restriction.\n\n9. At Un'sok, keep him alive and kill Living Amber in one small location until eight Burning Amber pools overlap. Track the criterion before killing him; do not consume the needed pools. If transformed, use the construct controls carefully and preserve your willpower while the other player handles remaining setup.\n\n10. At Shek'zeer, wait for her add phase, gather the two Kor'thik Reavers and kill them within ten seconds of one another. Then finish the Empress. Ensure every Heart of Fear Heroic boss credit is obtained.\n\n11. Enter Heroic Terrace of Endless Spring in the Veiled Stair. For Power Overwhelming, kill the Protectors in an order leaving a missing protector last: Kaolan, Asani or Regail. Repeat on later eligible clears until all three last-survivor credits are checked; do not assume raid-size changes refresh the weekly lockout.\n\n12. At Tsulong, keep the Enchanted Plant in the northeast alive; heal it if the night phase damages it, or finish quickly before it dies. Complete the Heroic Tsulong credit.\n\n13. Before Lei Shi dies, EVERY player must enter the surrounding water and let a Parasitoid Sha attach, gaining Parasitic Clutch. Dismount and remove effects that prevent parasites. Keep the debuff for the kill and obtain Heroic Lei Shi as well.\n\n14. For Sha of Fear, stand in the safe light protection during Breath of Fear and avoid Dread Spray if sent to a side platform; no raid member may be feared. The required The Mind-Killer criterion allows Normal or Heroic.\n\n15. Review 6932 after each raid. Revisit only missing Heroic/mechanic criteria on an eligible lockout, then collect the Heavenly Crimson Cloud Serpent from the journal/mail. Do not replace personal criteria with the separate guild final-boss achievement.",
    },
    [127170] = {
        category = "Dungeon and Raids",
        source = "Elegon in Mogu'shan Vaults",
        npcId = 60410,
        description = "Rare legacy raid drop on Normal or Heroic, in either raid size. Raid Finder does not award it.",
        difficulty = "hard",
        difficultyReason = "An easy legacy boss but a random drop constrained by weekly raid eligibility.",
        commentIds = { 1747900, 1795275, 1844308, 2493705 },
        tips = "Normal/Heroic and 10/25 use this raid's shared legacy weekly lockout; changing size or difficulty is not four independent mount attempts. Bonus rolls cannot award these instanced raid mounts.",
        waypoints = { { mapID = 379, x = 0.596, y = 0.391, step = 1, label = "Mogu'shan Vaults - Normal / Heroic raid entrance" } },
        reviewedAt = "2026-11-13",
        itemId = 87777,
        name = "Astral Cloud Serpent",
        wowheadUrl = "https://www.wowhead.com/item=87777",
        mountCategory = "Dungeon and Raids",
        stepCount = 4,
        acquisition = "Difficulty: Hard - An easy legacy boss but a random drop constrained by weekly raid eligibility.\n\n1. Set legacy raid difficulty to Normal or Heroic before entering Mogu'shan Vaults at the marked outdoor entrance. Use an appropriately high-level character. Do not enter the Raid Finder version for the mount.\n\n2. Clear Stone Guard, Feng, Gara'jal and the Spirit Kings, then enter Elegon's circular platform room. Kill Elegon and loot the boss/reward. He is the fifth boss, not the final Will of the Emperor encounter.\n\n3. Check your bags and the loot window for Astral Cloud Serpent. Use the item if it drops. Save bonus-roll tokens for the outdoor Pandaria world bosses; an extra raid roll cannot produce this mount.\n\n4. If no mount drops, return on the next weekly reset or run the raid on another character. Check Raid Info before accepting a saved group's lockout; Reset All Instances does not restore a killed weekly boss.",
    },
