            { mapID = 390, x = 0.35600000000000004, y = 0.26, step = 3, label = "Alani's western aerial circuit" },
            { mapID = 390, x = 0.386, y = 0.6459999999999999, step = 3, label = "Alani's southwestern aerial circuit" },
